INSERT INTO `monitoring_categories` (`id`, `code`, `name`, `short_title`, `description`, `icon`, `badge_color`, `target_annual`, `unit`, `created_at`, `material_icon`) VALUES ('1', 'spektrum_frekuensi', 'Monitoring SFR (Spektrum Frekuensi Radio)', 'Monitoring SFR', 'Pengawasan dan monitoring penggunaan spektrum frekuensi radio untuk memastikan kepatuhan terhadap Izin Stasiun Radio (ISR) dan parameter teknis pancaran.', 'fa-tower-broadcast', 'primary', '120', 'Kanal / Stasiun', '2026-09-25 11:49:15', 'cell_tower');
INSERT INTO `monitoring_categories` (`id`, `code`, `name`, `short_title`, `description`, `icon`, `badge_color`, `target_annual`, `unit`, `created_at`, `material_icon`) VALUES ('2', 'microwavelink', 'Inspeksi Microwavelink', 'Microwavelink', 'Inspeksi teknis stasiun radio gelombang mikro (microwave link) point-to-point untuk cross-polarization, frekuensi carrier, dan koordinasi kanal seluler/backhaul.', 'fa-network-wired', 'info', '80', 'Hop Link', '2026-09-25 11:49:15', 'settings_input_antenna');
INSERT INTO `monitoring_categories` (`id`, `code`, `name`, `short_title`, `description`, `icon`, `badge_color`, `target_annual`, `unit`, `created_at`, `material_icon`) VALUES ('3', 'radio_fm', 'Pengukuran Stasiun Radio Siaran FM', 'Radio Siaran FM', 'Pengukuran deviasi frekuensi maksimum (±75 kHz), kuat medan, bandwidth pancaran, dan harmonisa stasiun siaran radio FM komersial dan komunitas.', 'fa-radio', 'success', '60', 'Stasiun', '2026-09-25 11:49:15', 'radio');
INSERT INTO `monitoring_categories` (`id`, `code`, `name`, `short_title`, `description`, `icon`, `badge_color`, `target_annual`, `unit`, `created_at`, `material_icon`) VALUES ('4', 'tv_digital', 'Pengukuran Stasiun TV Digital', 'TV Digital', 'Pengukuran kualitas pancaran televisi siaran digital terrestrial DVB-T2 mencakup Modulation Error Rate (MER), Bit Error Rate (BER), dan level sinyal (dBm).', 'fa-tv', 'warning', '50', 'Mux Kanal', '2026-09-25 11:49:15', 'live_tv');
INSERT INTO `monitoring_categories` (`id`, `code`, `name`, `short_title`, `description`, `icon`, `badge_color`, `target_annual`, `unit`, `created_at`, `material_icon`) VALUES ('5', 'monitoring_hf', 'Monitoring HF (High Frequency)', 'Monitoring HF', 'Pemantauan spektrum frekuensi tinggi (HF 3 - 30 MHz) untuk maritim (distress frequency), penerbangan aeronautikal jarak jauh, dan radio komunikasi kebencanaan.', 'fa-wave-square', 'secondary', '45', 'Kanal HF', '2026-09-25 11:49:15', 'waves');
INSERT INTO `monitoring_categories` (`id`, `code`, `name`, `short_title`, `description`, `icon`, `badge_color`, `target_annual`, `unit`, `created_at`, `material_icon`) VALUES ('6', 'alat_telekomunikasi', 'Monitoring APT (Alat & Perangkat Telekomunikasi)', 'Monitoring APT', 'Pengawasan peredaran alat dan perangkat telekomunikasi (label sertifikasi Ditjen SDPPI, verifikasi IMEI, dan standarisasi perangkat nirkabel di pasar ritel/distributor).', 'fa-walkie-talkie', 'danger', '90', 'Toko / Vendor', '2026-09-25 11:49:15', 'devices');
