-- -------------------------------------------------------------
-- Table structure for table `monitoring_schedules`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `monitoring_schedules`;
CREATE TABLE `monitoring_schedules` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `spt_number` VARCHAR(100) NOT NULL ,
  `title` VARCHAR(255) NOT NULL ,
  `category_id` INT NOT NULL ,
  `leader_id` INT NOT NULL ,
  `member_names` TEXT NOT NULL ,
  `location` VARCHAR(255) NOT NULL ,
  `target_object` VARCHAR(255) NOT NULL ,
  `start_date` DATE NOT NULL ,
  `end_date` DATE NOT NULL ,
  `status` VARCHAR(30) NULL DEFAULT 'scheduled',
  `notes` TEXT NULL DEFAULT '',
  `created_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  `category_ids` TEXT NULL ,
  `spt_date` DATE NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

