-- -------------------------------------------------------------
-- Table structure for table `monitoring_reports`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `monitoring_reports`;
CREATE TABLE `monitoring_reports` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `report_code` VARCHAR(50) NOT NULL ,
  `category_id` INT NOT NULL ,
  `title` VARCHAR(255) NOT NULL ,
  `user_id` INT NOT NULL ,
  `target_name` VARCHAR(200) NOT NULL ,
  `frequency` VARCHAR(100) NULL DEFAULT '',
  `location` VARCHAR(255) NOT NULL ,
  `latitude` REAL NULL DEFAULT -0.502106,
  `longitude` REAL NULL DEFAULT 117.153709,
  `date_monitored` DATE NOT NULL ,
  `status` VARCHAR(30) NULL DEFAULT 'draft',
  `verified_by` INT NULL DEFAULT NULL,
  `verified_at` DATETIME NULL DEFAULT NULL,
  `verification_notes` TEXT NULL DEFAULT '',
  `attachments` TEXT NULL DEFAULT '',
  `technical_data` TEXT NULL DEFAULT '{}',
  `created_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

