INSERT INTO `monitoring_reports` (`id`, `report_code`, `category_id`, `title`, `user_id`, `target_name`, `frequency`, `location`, `latitude`, `longitude`, `date_monitored`, `status`, `verified_by`, `verified_at`, `verification_notes`, `attachments`, `technical_data`, `created_at`, `updated_at`) VALUES ('37', 'PEN-SPF-2026-003', '7', 'Sanksi Denda Administratif Penggunaan SFR Tanpa Izin - PT PERDANA TEKNOLOGI PERSADA', '1', 'PERDANA TEKNOLOGI PERSADA, PT - 2 Link PtP RLAN Sangatta Kutim', '5825 MHz & 5700 MHz (Point to Point RLAN)', 'Jl. Soekarno Hatta Ruko 5 RT 26, Sangatta Utara, Kutai Timur', '0.496521', '117.541235', '2026-05-13', 'verified', '1', '2026-10-12 01:46:37', 'Surat Tagihan Denda Administratif resmi telah diterbitkan Kepala Balai Monitor', '', '{\"warrant_number\":\"Surat Tagihan No: 2000397\\/BALMON.64\\/KU.03.02\\/05\\/2026\",\"violation_type\":\"Tanpa ISR (Stasiun Radio Ilegal)\",\"violator_identity\":\"PERDANA TEKNOLOGI PERSADA, PT \\/ Client ID: 00122134\",\"action_type\":\"Penghentian Pancaran Secara Sukarela\",\"evidence_items\":\"1 unit Mikrotik NetMetal ac2 & 1 unit Ubiquiti AF-5XHD. Total Denda: Rp 30.030.000. Kode Billing: 820260513325436\",\"bap_number\":\"BA Penghentian SFR No. T-106\\/BALMON.64\\/SP.03.03\\/05\\/2026\",\"ppns_officer\":\"PPNS Balai Monitor Kelas I Samarinda\",\"legal_followup\":\"Surat Peringatan 1 (SP1)\"}', '2026-10-12 01:46:37', '2026-10-12 01:46:37');
INSERT INTO `monitoring_reports` (`id`, `report_code`, `category_id`, `title`, `user_id`, `target_name`, `frequency`, `location`, `latitude`, `longitude`, `date_monitored`, `status`, `verified_by`, `verified_at`, `verification_notes`, `attachments`, `technical_data`, `created_at`, `updated_at`) VALUES ('38', 'PEN-SPF-2026-004', '7', 'Sanksi Denda Administratif Penggunaan SFR Tanpa Izin - PT HAMPARAN ANUGRAH ABADI', '1', 'PT. Hamparan Anugrah Abadi - 4 Frekuensi Handy Talkie / Mobile Unit (36 Unit)', '167.750, 167.525, 151.725, 160.250 MHz (VHF Land Mobile)', 'Jl. Pulau Manimbora No.88, Tanjung Redeb, Kab. Berau', '2.153214', '117.492145', '2026-07-06', 'verified', '1', '2026-10-12 01:46:37', 'Surat Tagihan Denda Administratif resmi telah diterbitkan Kepala Balai Monitor', '', '{\"warrant_number\":\"Surat Tagihan No: 2000417\\/BALMON.64\\/KU.03.02\\/07\\/2026\",\"violation_type\":\"Tanpa ISR (Stasiun Radio Ilegal)\",\"violator_identity\":\"PT. Hamparan Anugrah Abadi \\/ NIB: 9120300192116\",\"action_type\":\"Penghentian Pancaran Secara Sukarela\",\"evidence_items\":\"4 kanal frekuensi radio VHF HT\\/Mobile (total 36 unit). Total Denda: Rp 15.195.600. Kode Billing: 820260706982766\",\"bap_number\":\"BA Penghentian SFR No. T-156\\/BALMON.64\\/SP.03.03\\/06\\/2026\",\"ppns_officer\":\"PPNS Balai Monitor Kelas I Samarinda\",\"legal_followup\":\"Surat Peringatan 1 (SP1)\"}', '2026-10-12 01:46:37', '2026-10-12 01:46:37');

-- -------------------------------------------------------------
-- Table structure for table `perjanjian_kinerja`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `perjanjian_kinerja`;
CREATE TABLE `perjanjian_kinerja` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `year` INT NOT NULL DEFAULT 2026,
  `code` VARCHAR(20) NOT NULL ,
  `title` VARCHAR(255) NOT NULL ,
  `indicator` TEXT NOT NULL ,
  `target_annual` REAL NOT NULL ,
  `unit` VARCHAR(50) NULL DEFAULT '%',
  `realization` REAL NULL DEFAULT 0,
  `formula` TEXT NOT NULL ,
  `manual_measurement` TEXT NOT NULL ,
  `app_reference` VARCHAR(100) NULL DEFAULT '',
  `icon` VARCHAR(50) NULL DEFAULT 'insights',
  `badge_color` VARCHAR(30) NULL DEFAULT 'primary',
  `order_num` INT NULL DEFAULT 1,
  `notes` TEXT NULL DEFAULT '',
  `created_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for table `perjanjian_kinerja`
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('1', '2026', 'PK.1', 'Monitoring Pita Frekuensi Radio di Kabupaten/Kota', 'Persentase (%) Monitoring Penggunaan Spektrum Frekuensi Radio dan Pengenaan Sanksi Terhadap Pengguna Spektrum Frekuensi Radio di Kabupaten/Kota', '80', '%', '90', '(Jumlah Kab/Kota Termonitor / 10 Kab/Kota Wilayah Kerja UPT) x 100%', 'Perhitungan capaian mengacu pada 5 parameter: 1) 80% Kab/Kota termonitor; 2) 15 Pita Frekuensi Radio termonitor; 3) 60% ISR termonitor (1.312 dari 2.186 ISR); 4) 100% Hasil monitor SFR teridentifikasi; 5) 100% Tindak lanjut sanksi pelanggaran (jika ada temuan = 0). Laporan disampaikan melalui Report Online (ROL).', 'Report Online (ROL)', 'radar', 'primary', '1', 'Diperbarui via Impor Berkas (Hasil_Monitoring_SFR_Kaltim_TW1.csv) pada 07 Oct 2026 17:57. Realisasi: 9/10 Kab/Kota termonitor (90%).', '2026-10-08 02:15:51', '2026-10-08 02:15:51');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('2', '2026', 'PK.2', 'Pemeriksaan Stasiun', 'Persentase (%) Pemeriksaan Stasiun Radio Dan Pengenaan Sanksi Pelanggaran Terhadap Pemeriksaan Stasiun Radio', '100', '%', '91.82', '(Total Capaian Pemeriksaan Stasiun (FM + TV + Remote Site + Open Shelter) / Total Target 2.383) x 100%', 'Microwave link remote site min 80% & open shelter min 60% via APSTARD; Pengukuran parameter teknis Radio FM min 50 ISR (Balmon Samarinda: 76 ISR); TV Digital min 20 ISR.', 'APSTARD & ROL', 'settings_input_antenna', 'info', '2', 'Total Target: 2.383 Stasiun. Realisasi s.d. September: 2.188 Stasiun (91.82%). Komponen: FM 50/50 (100%), TV 17/18 (94.44%), Remote Site 1.791/2.053 (87.25%), Open Shelter 330/262 (125.86%).', '2026-10-08 02:15:51', '2026-10-08 02:15:51');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('3', '2026', 'PK.3', 'Penyelesaian Gangguan Frekuensi Radio', 'Persentase (%) Penyelesaian Gangguan Spektrum Frekuensi Radio', '100', '%', '100', '(Jumlah Gangguan SFR yang Terselesaikan / Jumlah Total Gangguan SFR) x 100%', '100% aduan tertangani via SPT (1x24 jam untuk dinas keselamatan, 7x24 jam non-keselamatan). 95% terselesaikan dengan status closed di aplikasi trouble ticket / Nota Dinas.', 'Trouble Ticket SFR', 'warning_amber', 'danger', '3', 'Realisasi TA 2026: 100.0% (Target: 100%). Total 2 kasus pengaduan resmi (PT. Kideco Jaya Agung di Kab. Paser pada April 2026 dan PT. Multi Harapan Utama di Kab. Kukar pada Agustus 2026), keduanya tertangani dan terselesaikan tuntas 100% (Clean - Bebas Gangguan) dengan penerbitan BAP dan penghentian sumber gangguan. Bulan lainnya nihil/tidak ada kegiatan penanganan gangguan.', '2026-10-08 02:15:51', '2026-10-08 02:15:51');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('4', '2026', 'PK.4', 'Pengawasan Alat dan/atau Perangkat Telekomunikasi', 'Persentase (%) Pengawasan Alat dan/atau Perangkat Telekomunikasi (Monitoring APT)', '100', '%', '100', '((1.052 Perangkat Bersertifikat + 0 Pelanggaran Perangkat) / 300 Target Perangkat Termonitor) x 100% = 100%', '1. Dasar Pelaksanaan: Nota Dinas Direktur Pengendalian Infrastruktur Digital Nomor: 224/DJID.6/PR.04.01/02/2026 tanggal 03 Februari 2026.
2. Target UPT: 8 Kabupaten/Kota di monitor dengan Target Jumlah Perangkat 300 unit.
3. Prioritas Perangkat: Mobile Transceiver/Radio Rig, Handy Talkie, Wireless Access Point (Wifi Extender, Wireless Repeater Router).
4. Lingkup 16 Jenis Perangkat: HF All Band Transceiver, Wireless Access Point, Pemancar FM, Simbox, Repeater GSM, Radio RIG, GPS Tracker, Microwave Link (IDU/ODU), Handy Talkie, Set Top Box, Perangkat Low Power, Optical Line Terminal, Radio POC, Jammer, Fake BTS, dan APT Rakitan.
5. Realisasi s.d. September 2026 (Cutoff 01 Oktober 2026): 8 Kabupaten/Kota telah dimonitor, total 1.052 perangkat termonitor (1.052 bersertifikat, 0 pelanggaran), capaian 100%.
6. Pelaporan: Aplikasi SMART (smart.postel.go.id).', 'Aplikasi SMART (smart.postel.go.id)', 'devices_other', 'warning', '4', 'Laporan Capaian PK Pengawasan APT Balmon Samarinda Bulan September 2026 (Cutoff Data per Tanggal 01 Oktober 2026). Ditandatangani Kepala Balai Monitor Edi Mulyono tanggal 05 Oktober 2026.', '2026-10-08 02:15:51', '2026-10-09 08:16:44');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('5', '2026', 'PK.5', 'Kepatuhan Standar Teknis & Sanksi APT', 'Persentase (%) Tingkat Kepatuhan Standar Teknis Alat dan/atau Perangkat Telekomunikasi dan Digital', '100', '%', '100', '(Σ Tindak Lanjut Pelanggaran / Σ Total Data Pelanggaran) x 100%', '100% pelanggaran ditindaklanjuti dengan penerbitan Surat Teguran administratif dan pelaporan via aplikasi SMART dan tautan resmi Komdigi.', 'Aplikasi SMART', 'gavel', 'dark', '5', 'Pelanggaran wajib dimonitor kembali setelah 7 hari kalender sejak teguran tertulis diterima.', '2026-10-08 02:15:51', '2026-10-08 02:15:51');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('6', '2026', 'PK.6', 'Operasional & SLA Stasiun Monitor (SMFR)', 'Persentase (%) Terjaganya Operasional Dan Fungsi Monitoring Dari Stasiun Monitor Frekuensi Radio di UPT', '86', '% SLA', '92.25', '(SLA Stasiun Monitor Tetap/Transportable + SLA Stasiun Bergerak) / 2', 'Stasiun Tetap/Transportable: SLA 100% jika upload data okupansi SMSN min 1x/minggu (4x/bulan). Bergerak: SLA 100% jika upload min 1x/bulan. Pelaporan via smfr.postel.go.id/v2/ & SMSN.', 'SMFR v2 & SMSN', 'cell_tower', 'success', '6', 'Realisasi rata-rata s.d. Mei 2026: 92.25% (Target: 86%, Kualitas: 100%). Januari: 94.38%, Februari: 92.50%, Maret: 92.50%, April: 92.50%, Mei: 89.38%. Terjaganya operasional 3 Stasiun Transportable, 1 Stasiun Bergerak DF, dan Stasiun Tetap VUHF Samarinda.', '2026-10-08 02:15:51', '2026-10-08 02:15:51');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('7', '2026', 'PK.7', 'Penanganan Sanksi Denda Administratif', 'Persentase (%) Penanganan Sanksi Denda Administratif', '85', '%', '95', '(Σ Surat Tagihan Terbayar + (Bobot x Tindak Lanjut Surat Tagihan Belum Terbayar)) / Σ Total Surat Tagihan x 100%', 'Pengelolaan Surat Tagihan denda pelanggaran IPFR/SFR/APT untuk optimalisasi PNBP. Target bertahap: TW I >= 60%, TW II >= 65%, TW III >= 70%, TW IV >= 75%, Des 81%, Tahunan 85%.', 'Aplikasi Denda Administratif', 'payments', 'secondary', '7', 'Total Ketetapan Denda TA 2026: Rp 201.258.400 (4 Surat Tagihan Denda SPP I: PLN Rp 135.935.800, PT Lintasmaya Rp 20.097.000, PT Perdana Tekno Rp 30.030.000, PT Hamparan Anugrah Abadi Rp 15.195.600). 100% dari 4 Surat Tagihan diterbitkan & ditindaklanjuti sesuai prosedur PP 43/2023, PP 28/2025, dan Perdirjen SDPPI 3/2024.', '2026-10-08 02:15:51', '2026-10-08 02:15:51');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('8', '2026', 'PK.8', 'Data Kualitas Layanan Seluler (QoS)', 'Persentase (%) Tersedianya Data Hasil Pengukuran Kualitas Layanan', '100', '% Kab/Kota', '100', '(Jumlah Kab/Kota yang Sudah Diukur / Jumlah 80% Kab/Kota Wilayah Kerja) x 100%', 'Pengukuran kualitas layanan telekomunikasi di 80% Kab/Kota wilayah kerja UPT via Drive Test (min 5 jam kecepatan ~40 km/jam) dan Static Test (min 3 PoI per kab/kota). Post-processing via PMT.', 'Pusat Monitoring Telekomunikasi (PMT)', 'speed', 'info', '8', 'Realisasi s.d. Oktober 2026: 100.0% (Target: 100% / 8 Kab/Kota wilayah kerja). Telah terlaksana pengukuran Drive Test & Static Test di 8 Kabupaten/Kota (Samarinda, Balikpapan, Kukar, Bontang, PPU/IKN, Kutim, Berau, Paser) serta validasi integrasi PMT Komdigi.', '2026-10-08 02:15:51', '2026-10-08 02:15:51');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('31', '2025', 'PK.1', 'Persentase Monitoring Penggunaan Spektrum Frekuensi Radio', 'Monitoring pita frekuensi radio di Kabupaten/Kota dilaksanakan melalui kegiatan observasi dan identifikasi spektrum frekuensi radio (15 pita frekuensi, 60% ISR, 80% teridentifikasi, 100% tindak lanjut sanksi)', '80', '%', '85', '(Jumlah Kabupaten Kota Termonitor ÷ Jumlah Kabupaten Kota Wil. Kerja UPT) × 100%', 'Observasi 15 subservice/pita frekuensi; 60% ISR termonitor; 80% hasil monitor teridentifikasi; 100% tindaklanjut pengenaan sanksi; observasi min 1x/bulan per-stasiun tetap/transportable. Evaluasi di 10 Kab/Kota Kaltim.', 'Report Online (ROL)', 'radar', 'primary', '1', 'Target 80% Kab/Kota termonitor terlampaui dengan capaian 85%.', '2026-10-09 04:59:59', '2026-10-09 04:59:59');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('32', '2025', 'PK.2', 'Pemeriksaan Stasiun Radio', 'Pemeriksaan stasiun radio microwave link (remote site min 80% & open shelter min 60%), serta pengukuran parameter teknis pemancar stasiun siaran Radio FM & TV Digital', '100', '%', '94.2', '[(Jumlah yang dilakukan Pemeriksaan Stasiun Radio + Data Tindak Lanjut Pelanggaran Disanksi) ÷ (Total Data Target Pemeriksaan Stasiun + Total Pelanggaran)] × 100%', 'Pemeriksaan Microwave link melalui Remote Site dan Open Shelter; Pengukuran parameter teknis Radio FM (target 50 ISR untuk UPT >50 ISR, Samarinda 75 ISR) dan TV Digital pada APSTARD & ROL.', 'APSTARD & ROL', 'settings_input_antenna', 'info', '2', 'Realisasi evaluasi tahun 2025 mencapai 94.2% dari target 100%.', '2026-10-09 04:59:59', '2026-10-09 04:59:59');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('33', '2025', 'PK.3', 'Penanganan Gangguan SFR', 'Penanganan aduan gangguan spektrum frekuensi radio pada seluruh dinas berdasarkan aduan pemegang IPFR sesuai SOP dengan batas waktu penerbitan SPT', '95', '%', '100', '(Jumlah Gangguan SFR yang Ditangani ÷ Jumlah Total Gangguan SFR) × 100%', 'Penghitungan penanganan gangguan SFR dilakukan terhadap seluruh dinas/service (mengecualikan gangguan HF, perbatasan, dan internasional). Waktu terbit SPT: Dinas keselamatan max 1x24 jam, dinas non-keselamatan max 7x24 jam.', 'Trouble Ticket (laporgangguansfr.postel.go.id)', 'warning', 'danger', '3', 'Target 95% tertangani tercapai sempurna dengan realisasi 100% aduan diselesaikan.', '2026-10-09 04:59:59', '2026-10-09 04:59:59');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('34', '2025', 'PK.4', 'Persentase Tingkat Kepatuhan Standar Teknis Alat dan/atau Perangkat Telekomunikasi dan Digital', 'Monitoring alat dan/atau perangkat telekomunikasi terhadap 16 jenis perangkat prioritas di 80% Kabupaten/Kota wilayah kerja UPT serta tindak lanjut sanksi administratif', '75', '%', '88.5', '[(∑ Perangkat Bersertifikat Termonitor + ∑ Pelanggaran Perangkat Ditindaklanjuti) ÷ ∑ Perangkat Termonitor] × 100%', 'Pengawasan 16 jenis perangkat prioritas di 80% Kab/Kota wilayah kerja UPT (8 dari 10 Kab/Kota Kaltim). Pelanggaran ditindaklanjuti sanksi administratif (Surat Teguran, BA Penghentian).', 'Aplikasi SMART', 'devices', 'warning', '4', 'Target 75% terlampaui dengan tingkat kepatuhan perangkat sebesar 88.5%.', '2026-10-09 04:59:59', '2026-10-09 04:59:59');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('35', '2025', 'PK.5', 'Persentase Terjaganya Operasional dan Fungsi Monitoring Stasiun Monitor Frekuensi Radio di UPT (SLA SMFR)', 'Ketersediaan dan keandalan operasional stasiun monitor tetap/transportable dan stasiun monitor bergerak UPT dalam menyampaikan data monitoring spektrum frekuensi radio', '85', '%', '87.8', '[ (∑ SLA Stasiun Monitor Tetap/Transportable ÷ ∑ Stasiun Tetap) + (∑ SLA Stasiun Bergerak ÷ ∑ Stasiun Bergerak) ] ÷ 2', 'SLA Tetap/Transportable = 100% bila lapor ROL min 1x/bulan dan SMSN min 4x/bulan (1x/minggu). SLA Bergerak = 100% bila lapor ROL min 1x/bulan. Jika rusak dihitung rasio perangkat baik per total perangkat.', 'Aplikasi Pemeliharaan SMFR, ROL, SMSN', 'cell_tower', 'success', '5', 'Target 85% terlampaui dengan rata-rata ketersediaan operasional sensor 87.8%.', '2026-10-09 04:59:59', '2026-10-09 04:59:59');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('36', '2025', 'PK.6', 'Persentase Penanganan Sanksi Denda Administratif', 'Tindak lanjut dan penyelesaian sanksi denda administratif atas pelanggaran penggunaan spektrum frekuensi radio dan alat/perangkat telekomunikasi sesuai regulasi PNBP', '80', '%', '96', '[ (∑ Inv. Denda Terbayar + (Bobot × Tindak Lanjut Inv. Belum Terbayar) + Inv. Baru Belum Jatuh Tempo) ÷ ∑ Inv. Denda Administratif ] × 100%', 'Target berjenjang: TW I (60%), TW II (65%), TW III (70%), TW IV (75%), Desember (80%). Bobot tindak lanjut: Reminder 1 (0.9), Reminder 2 (0.8), Reminder 3 (0.7), Pelimpahan KPKNL (0.6).', 'Aplikasi Denda Administratif', 'gavel', 'secondary', '6', 'Target 80% terlampaui dengan persentase penanganan sanksi denda mencapai 96.0%.', '2026-10-09 04:59:59', '2026-10-09 04:59:59');
INSERT INTO `perjanjian_kinerja` (`id`, `year`, `code`, `title`, `indicator`, `target_annual`, `unit`, `realization`, `formula`, `manual_measurement`, `app_reference`, `icon`, `badge_color`, `order_num`, `notes`, `created_at`, `updated_at`) VALUES ('37', '2025', 'PK.7', 'Tersedianya Data Hasil Pengukuran Kualitas Layanan (QoS)', 'Pengukuran standar kualitas layanan penyelenggaraan jaringan bergerak seluler (2G/3G/4G/5G) melalui Static Test dan Drive Test di 80% Kabupaten/Kota wilayah kerja UPT', '100', '%', '100', '(Jumlah Kab/Kota yang Sudah Diukur ÷ Jumlah 80% Kab/Kota Wilayah Kerja UPT) × 100%', 'Target monitoring kualitas layanan seluler dilaksanakan di 80% Kab/Kota (8 dari 10 Kab/Kota Kaltim). Pelaksanaan Static Test (POI) dan Drive Test (rute transportasi), serta pengiriman data log ke owncloud PMT.', 'Pusat Monitoring Telekomunikasi (PMT)', 'speed', 'info', '7', 'Target 100% tercapai penuh pada 8 Kabupaten/Kota wilayah kerja prioritas.', '2026-10-09 04:59:59', '2026-10-09 04:59:59');

