-- -------------------------------------------------------------
-- Table structure for table `notifications`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `user_id` INT NOT NULL ,
  `title` VARCHAR(150) NOT NULL ,
  `message` TEXT NOT NULL ,
  `link` VARCHAR(255) NULL DEFAULT '',
  `is_read` INT NULL DEFAULT 0,
  `created_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------------------
-- Table structure for table `import_history`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `import_history`;
CREATE TABLE `import_history` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `import_type` VARCHAR(50) NOT NULL ,
  `indicator_code` VARCHAR(20) NULL DEFAULT 'PK.1',
  `batch_code` VARCHAR(50) NOT NULL ,
  `original_filename` VARCHAR(255) NOT NULL ,
  `saved_filename` VARCHAR(255) NOT NULL ,
  `file_path` VARCHAR(255) NOT NULL ,
  `file_size` INT NULL DEFAULT 0,
  `file_extension` VARCHAR(10) NULL DEFAULT '',
  `total_rows` INT NULL DEFAULT 0,
  `valid_rows` INT NULL DEFAULT 0,
  `invalid_rows` INT NULL DEFAULT 0,
  `realization_before` REAL NULL DEFAULT NULL,
  `realization_after` REAL NULL DEFAULT NULL,
  `summary_result` TEXT NULL DEFAULT '',
  `status` VARCHAR(20) NULL DEFAULT 'success',
  `notes` TEXT NULL DEFAULT '',
  `user_id` INT NOT NULL ,
  `uploader_name` VARCHAR(150) NOT NULL ,
  `uploader_nip` VARCHAR(50) NULL DEFAULT '',
  `ip_address` VARCHAR(50) NULL DEFAULT '',
  `created_at` DATETIME NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

